// ---------------------------------------------------------------------------
// F1 / F3 — the redirected entry delivers the token to exile (CR 614.6, CR 111.7).
// ---------------------------------------------------------------------------

/// Events of `events` that put `object` somewhere, as `(from, to)`.
fn zone_moves_of(events: &[GameEvent], object: ObjectId) -> Vec<(Option<Zone>, Zone)> {
    events
        .iter()
        .filter_map(|event| match event {
            GameEvent::ZoneChanged {
                object_id,
                from,
                to,
                ..
            } if *object_id == object => Some((*from, *to)),
            _ => None,
        })
        .collect()
}

/// The `TokenCreated` object ids named `name` in `events`.
fn created_tokens_named(events: &[GameEvent], name: &str) -> Vec<ObjectId> {
    events
        .iter()
        .filter_map(|event| match event {
            GameEvent::TokenCreated {
                object_id,
                name: token_name,
                ..
            } if token_name == name => Some(*object_id),
            _ => None,
        })
        .collect()
}

/// F1. CR 111.1 + CR 614.6 + CR 111.7: under Hallowed Moonlight a created creature
/// token is still CREATED — Mirkwood Bats sees it, the first-creation ledger records
/// it — but it is put into exile instead of onto the battlefield, so no entry event
/// exists, and it ceases to exist at the next state-based action check.
#[test]
fn hallowed_moonlight_token_creation_is_observed_then_exiled() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let soldier = add_instant(&mut scenario, P0, "Recruit the Worthy", RECRUIT_THE_WORTHY);
    let treasure = add_sorcery(&mut scenario, P0, "Strike It Rich", STRIKE_IT_RICH);
    scenario.add_creature_from_oracle(P0, "Mirkwood Bats", 2, 3, MIRKWOOD_BATS);
    let mut runner = scenario.build();
    assert!(
        runner
            .state()
            .players_who_created_token_this_turn
            .is_empty(),
        "reach-guard: no token was created yet this turn"
    );
    cast_hallowed(&mut runner, hallowed);
    let life_before = runner.state().players[1].life;

    let outcome = runner.cast(soldier).resolve();
    assert_settled(outcome.state(), "F1 soldier");
    let created = created_tokens_named(outcome.events(), "Soldier");
    assert_eq!(created.len(), 1, "the creation is published once");
    assert_eq!(
        zone_moves_of(outcome.events(), created[0]),
        vec![(None, Zone::Exile)],
        "the token is created in exile: no battlefield entry event"
    );
    assert!(
        !outcome.state().objects.contains_key(&created[0]),
        "CR 111.7: the exiled token ceased to exist"
    );
    assert_eq!(
        outcome.state().players[1].life,
        life_before - 1,
        "Mirkwood Bats observed the creation"
    );
    assert!(
        outcome
            .state()
            .players_who_created_token_this_turn
            .contains(&P0),
        "the first-creation set records P0"
    );
    assert_eq!(
        outcome.state().created_tokens_this_turn.len(),
        1,
        "the turn's created-token ledger records the redirected creation"
    );

    // Negative control: a noncreature token is not redirected, still observed.
    let outcome = runner.cast(treasure).resolve();
    assert_settled(outcome.state(), "F1 treasure");
    let created = created_tokens_named(outcome.events(), "Treasure");
    assert_eq!(
        zone_moves_of(outcome.events(), created[0]),
        vec![(None, Zone::Battlefield)],
        "a noncreature token still enters the battlefield"
    );
    assert_eq!(outcome.state().players[1].life, life_before - 2);
}

/// Create one Elvish Visionary through the engine's debug Create Card entry as a
/// token (`run_etb` selects the consulting or the forced entry) and return the events.
fn debug_create_visionary_token(runner: &mut GameRunner, run_etb: bool) -> Vec<GameEvent> {
    let db = crate::support::shared_card_db().expect("the committed integration fixture loads");
    let face = db
        .get_face_by_name("Elvish Visionary")
        .expect("Elvish Visionary is in the committed fixture");
    create_debug_cards(
        runner.state_mut(),
        DebugCardCreateRequest {
            actor: P0,
            source: debug_card_entry_source(db, face),
            owner: P0,
            zone: Zone::Battlefield,
            count: 1,
            attach_to: None,
            run_etb,
            nonlegendary: false,
            creation_kind: DebugCardCreationKind::Token,
        },
    )
    .expect("the debug creation is accepted")
    .events
}

/// F3. CR 614.6 + CR 614.12: the public debug Create Card token entry proposes a
/// liminal `TokenEntry` directly (no `CreateToken` prepass). Under resolved Hallowed
/// Moonlight the token is exiled instead — it does not enter, so its "when this enters,
/// draw a card" never triggers — and the forced entry (`run_etb: false`) stays raw.
#[test]
fn hallowed_moonlight_redirects_a_debug_created_creature_token() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let mut runner = scenario.build();
    runner.state_mut().debug_mode = true;
    cast_hallowed(&mut runner, hallowed);
    let hand_before = runner.state().players[0].hand.len();

    let events = debug_create_visionary_token(&mut runner, true);
    let created = created_tokens_named(&events, "Elvish Visionary");
    assert_eq!(created.len(), 1, "the debug creation is still a creation");
    assert_eq!(
        zone_moves_of(&events, created[0]),
        vec![(None, Zone::Exile)],
        "the token goes to exile, not the battlefield"
    );
    assert!(
        battlefield_named(runner.state(), "Elvish Visionary").is_empty(),
        "no Elvish Visionary entered"
    );
    assert!(
        !runner.state().objects.contains_key(&created[0]),
        "CR 111.7: the exiled token ceased to exist"
    );
    assert_eq!(
        runner.state().players[0].hand.len(),
        hand_before,
        "it never entered, so its enter trigger did not draw"
    );
    assert_settled(runner.state(), "F3 consulting entry");

    // CR 614.6 control: the forced entry (no replacement consult) is unchanged.
    let events = debug_create_visionary_token(&mut runner, false);
    let created = created_tokens_named(&events, "Elvish Visionary");
    assert_eq!(created.len(), 1);
    assert_eq!(
        battlefield_named(runner.state(), "Elvish Visionary").len(),
        1,
        "the raw placement still puts the token on the battlefield"
    );
}

/// F1 (CR 733 journal + save/reopen). The redirected creation journals its birth in the
/// zone it was created in, replays against the captured predecessor to the same
/// zone-change record the live creation made, and a saved-and-reopened game continues:
/// the next token creation works and is observed.
#[test]
fn redirected_token_creation_replays_and_survives_save_reopen() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let soldier = add_instant(&mut scenario, P0, "Recruit the Worthy", RECRUIT_THE_WORTHY);
    let treasure = add_sorcery(&mut scenario, P0, "Strike It Rich", STRIKE_IT_RICH);
    let mut runner = scenario.build();
    cast_hallowed(&mut runner, hallowed);

    let committed = runner.cast(soldier).commit();
    let pre_state = committed.state().clone();
    let window = pre_state.resolved_rules_journal.entries().len();
    let outcome = committed.resolve();
    let state = outcome.state().clone();
    let token_id = created_tokens_named(outcome.events(), "Soldier")[0];

    let commands: Vec<ResolvedRulesCommand> = state
        .resolved_rules_journal
        .entries()
        .iter()
        .skip(window)
        .filter_map(|entry| entry.command.clone())
        .collect();
    let births: Vec<_> = commands
        .iter()
        .filter_map(|command| match command {
            ResolvedRulesCommand::TokenCreation(birth) if birth.object.object_id == token_id => {
                Some(birth.clone())
            }
            _ => None,
        })
        .collect();
    assert_eq!(births.len(), 1, "one journaled birth");
    assert_eq!(births[0].entry_zone, Some(Zone::Exile), "born in exile");
    assert!(
        commands.iter().any(|command| matches!(
            command,
            ResolvedRulesCommand::ObjectCease(cease) if cease.object.object_id == token_id
                && cease.expected_zone == Zone::Exile
        )),
        "the exiled token's cease-to-exist is journaled from exile"
    );

    // Replay the birth and the cease against the captured predecessor.
    let mut replay = pre_state;
    engine::game::effects::token::apply_resolved_token_creation(&mut replay, &births[0])
        .expect("the redirected birth replays");
    assert_eq!(replay.objects[&token_id].zone, Zone::Exile);
    assert!(
        !replay.battlefield.contains(&token_id),
        "replay never puts the redirected token on the battlefield"
    );
    let live_record = state
        .zone_changes_this_turn
        .iter()
        .find(|record| record.object_id == token_id)
        .expect("the live creation recorded its zone change");
    assert_eq!(live_record.to_zone, Zone::Exile);
    let replayed_record = replay
        .zone_changes_this_turn
        .iter()
        .find(|record| record.object_id == token_id)
        .expect("replay records the birth");
    assert_eq!(
        replayed_record, live_record,
        "the replayed record equals the live one"
    );
    for command in &commands {
        if let ResolvedRulesCommand::ObjectCease(cease) = command {
            if cease.object.object_id == token_id {
                engine::game::zones::apply_resolved_object_cease(&mut replay, cease)
                    .expect("the cease replays from exile");
            }
        }
    }
    assert!(
        !replay.objects.contains_key(&token_id),
        "replayed token ceased"
    );

    // Save, reopen and take the next action.
    let json = serde_json::to_string(&PersistedGameState::capture(state.clone()))
        .expect("state serializes");
    let restored = serde_json::from_str::<PersistedGameState>(&json)
        .expect("persisted state decodes")
        .prepare_for_restore(PersistedRestoreFinalization::DeferUntilRehydrated)
        .expect("persisted state is admissible")
        .finalize_after_rehydration(|_| Ok(()))
        .expect("restored state is publishable");
    let mut reopened = GameRunner::from_state(restored);
    let outcome = reopened.cast(treasure).resolve();
    assert_settled(outcome.state(), "after save/reopen");
    assert_eq!(
        battlefield_tokens_named(outcome.state(), "Treasure").len(),
        1,
        "the reopened game keeps resolving token creations"
    );
}

// ---------------------------------------------------------------------------
// F2 — a copy batch's entrant gets its own as-enters copy choice before the redirect.
// ---------------------------------------------------------------------------

/// Verbatim Oracle text of Phyrexian Metamorph (Scryfall), minus its reminder text.
const PHYREXIAN_METAMORPH: &str = "You may have this creature enter as a copy of any artifact \
or creature on the battlefield, except it's an artifact in addition to its other types.";

/// Verbatim Oracle text of Mimic Vat (Scryfall).
const MIMIC_VAT: &str = "Imprint — Whenever a nontoken creature dies, you may exile that card. \
If you do, return each other card exiled with this artifact to its owner's graveyard.\n{3}, \
{T}: Create a token that's a copy of a card exiled with this artifact. It gains haste. Exile it \
at the beginning of the next end step.";

/// Verbatim Oracle text of March of the Machines (Scryfall).
const MARCH_OF_THE_MACHINES: &str = "Each noncreature artifact is an artifact creature with power \
and toughness each equal to its mana value. (Equipment that's a creature can't equip a creature.)";

/// How the Metamorph token's as-enters copy is answered.
#[derive(Clone, Copy, PartialEq, Eq)]
enum MetamorphAnswer {
    /// Copy the Mimic Vat itself (a noncreature artifact).
    CopyVat,
    /// Copy Grizzly Bears (a creature).
    CopyBears,
    /// Decline the copy: the token stays a Phyrexian Metamorph creature.
    Decline,
}

/// What a Mimic Vat activation over an imprinted Phyrexian Metamorph went through.
struct VatRun {
    prompts: Vec<String>,
    runner: GameRunner,
    events: Vec<GameEvent>,
}

/// Answer every prompt until priority settles with an empty stack, recording each.
fn drive_prompts(
    runner: &mut GameRunner,
    answer: MetamorphAnswer,
    vat: ObjectId,
    bears: ObjectId,
    prompts: &mut Vec<String>,
    events: &mut Vec<GameEvent>,
) {
    for _ in 0..40 {
        let result = match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => return,
            WaitingFor::Priority { .. } => runner.act(GameAction::PassPriority),
            WaitingFor::CopyTargetChoice { valid_targets, .. } => {
                prompts.push("CopyTargetChoice".to_string());
                let target = match answer {
                    MetamorphAnswer::CopyVat => vat,
                    MetamorphAnswer::CopyBears => bears,
                    MetamorphAnswer::Decline => panic!("a declined copy offers no target"),
                };
                assert!(valid_targets.contains(&target), "the model is offered");
                runner.act(GameAction::ChooseTarget {
                    target: Some(TargetRef::Object(target)),
                })
            }
            WaitingFor::ReplacementChoice { candidates, .. } => {
                prompts.push(format!(
                    "ReplacementChoice({:?})",
                    candidates
                        .iter()
                        .map(|c| c.description.clone())
                        .collect::<Vec<_>>()
                ));
                let accept = candidates
                    .iter()
                    .position(|c| c.description.contains("enter as a copy"));
                let decline = candidates.iter().position(|c| c.description == "Decline");
                let index = match (answer, accept, decline) {
                    (MetamorphAnswer::Decline, _, Some(index)) => index,
                    (_, Some(index), _) => index,
                    _ => 0,
                };
                runner.act(GameAction::ChooseReplacement { index })
            }
            WaitingFor::OptionalEffectChoice { .. } => {
                prompts.push("OptionalEffectChoice".to_string());
                runner.act(GameAction::DecideOptionalEffect { accept: true })
            }
            other => panic!("unexpected prompt {other:?} after {prompts:?}"),
        };
        events.extend(result.expect("the prompt answer is accepted").events);
    }
    panic!("prompts did not settle: {prompts:?}");
}

/// Verbatim Oracle text of Feldon of the Third Path (Scryfall).
const FELDON: &str = "{2}{R}, {T}: Create a token that's a copy of target creature card in your \
graveyard, except it's an artifact in addition to its other types. It gains haste. Sacrifice it \
at the beginning of the next end step.";

/// P0 controls Feldon of the Third Path, Mimic Vat (a noncreature artifact: the copy model) and
/// Grizzly Bears (a creature: the other model), with a printed 0/0 Phyrexian Metamorph in the
/// graveyard, and activates Feldon on the Metamorph card; when `moonlight`, Hallowed Moonlight
/// resolved first. The new token carries the Metamorph's as-enters copy, answered with `answer`.
///
/// Printed producer note: a Mimic Vat activation over a Metamorph that Vat itself imprinted
/// resolves `CopyTokenOf` with no token at the merge base (MEASURED with no Hallowed Moonlight
/// anywhere: "a card exiled with this artifact" finds no copy source), so Feldon of the Third
/// Path — the same shape, a token copy of a Metamorph card, with `spark_double_as_enters.rs` as
/// precedent — produces the entrant. Mimic Vat stays on the battlefield as the printed model.
fn run_vat(moonlight: bool, answer: MetamorphAnswer) -> VatRun {
    run_vat_with(moonlight, false, answer)
}

/// Verbatim Oracle text of Grumgully, the Generous (Scryfall).
const GRUMGULLY: &str =
    "Each other non-Human creature you control enters with an additional +1/+1 counter on it.";

/// [`run_vat`], optionally with March of the Machines on the battlefield (`march`): it makes
/// every noncreature artifact, the Vat and so a copy of it, an artifact creature.
fn run_vat_with(moonlight: bool, march: bool, answer: MetamorphAnswer) -> VatRun {
    run_vat_full(moonlight, march, false, answer)
}

/// [`run_vat_with`], optionally with Grumgully, the Generous (`grumgully`): its entry counter
/// rides the Metamorph token's batch.
fn run_vat_full(moonlight: bool, march: bool, grumgully: bool, answer: MetamorphAnswer) -> VatRun {
    let mut scenario = base_scenario();
    scenario.with_mana_pool(
        P0,
        (0..3)
            .map(|_| ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]))
            .collect(),
    );
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let feldon = scenario
        .add_creature_from_oracle(P0, "Feldon of the Third Path", 2, 3, FELDON)
        .as_legendary()
        .id();
    let vat = {
        let mut card = scenario.add_artifact_from_oracle(P0, "Mimic Vat", MIMIC_VAT);
        card.with_mana_cost(ManaCost::generic(3));
        card.id()
    };
    if march {
        scenario.add_enchantment_from_oracle(P0, "March of the Machines", MARCH_OF_THE_MACHINES);
    }
    if grumgully {
        scenario
            .add_creature_from_oracle(P0, "Grumgully, the Generous", 3, 3, GRUMGULLY)
            .as_legendary()
            .with_subtypes(vec!["Elemental"]);
    }
    let bears = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let metamorph = {
        let mut card = scenario.add_creature_to_graveyard(P0, "Phyrexian Metamorph", 0, 0);
        card.from_oracle_text(PHYREXIAN_METAMORPH)
            .as_artifact_creature()
            .with_subtypes(vec!["Phyrexian", "Shapeshifter"]);
        card.id()
    };
    let mut runner = scenario.build();
    if moonlight {
        cast_hallowed(&mut runner, hallowed);
    }
    let mut prompts = Vec::new();
    let mut events = Vec::new();
    let result = runner
        .activate(feldon, 0)
        .target_object(metamorph)
        .resolve();
    events.extend(result.events().iter().cloned());
    drive_prompts(&mut runner, answer, vat, bears, &mut prompts, &mut events);
    VatRun {
        prompts,
        runner,
        events,
    }
}

fn offered_copy(run: &VatRun) -> bool {
    run.prompts
        .iter()
        .any(|prompt| prompt.contains("enter as a copy"))
}

/// F1 control. Without Hallowed Moonlight the Vat token copies the Vat and enters.
#[test]
fn metamorph_token_copying_the_vat_enters_without_moonlight() {
    let run = run_vat(false, MetamorphAnswer::CopyVat);
    assert!(offered_copy(&run), "the copy is offered: {:?}", run.prompts);
    assert_eq!(
        battlefield_tokens_named(run.runner.state(), "Mimic Vat").len(),
        1,
        "the Vat-copy token entered"
    );
    assert_settled(run.runner.state(), "F1 control");
}

/// F1. CR 616.1c + CR 614.12: under Hallowed Moonlight the Metamorph token's own copy
/// is offered first; choosing Mimic Vat makes the entrant a noncreature artifact, which
/// Moonlight ("if a creature would enter") does not touch, so it enters.
#[test]
fn metamorph_token_copying_the_vat_enters_under_moonlight() {
    let run = run_vat(true, MetamorphAnswer::CopyVat);
    assert!(offered_copy(&run), "the copy is offered: {:?}", run.prompts);
    let vats = battlefield_tokens_named(run.runner.state(), "Mimic Vat");
    assert_eq!(vats.len(), 1, "the noncreature Vat copy entered");
    let token = &run.runner.state().objects[&vats[0]];
    assert!(
        !token.card_types.core_types.contains(&CoreType::Creature),
        "the entered copy is not a creature"
    );
    assert_settled(run.runner.state(), "F1 enters");
}

/// F1 (reverse type direction + F3). Choosing Grizzly Bears makes the entrant a creature,
/// so Moonlight exiles it: the copy was offered and answered, and exactly one Grizzly
/// Bears token (the selected copy, not the Metamorph) was created, in exile.
#[test]
fn metamorph_token_copying_a_creature_is_created_in_exile_under_moonlight() {
    let run = run_vat(true, MetamorphAnswer::CopyBears);
    assert!(offered_copy(&run), "the copy is offered: {:?}", run.prompts);
    assert!(
        run.prompts
            .iter()
            .any(|prompt| prompt == "CopyTargetChoice"),
        "a model was chosen: {:?}",
        run.prompts
    );
    let created = created_tokens_named(&run.events, "Grizzly Bears");
    assert_eq!(created.len(), 1, "the selected copy is created once");
    assert_eq!(
        zone_moves_of(&run.events, created[0]),
        vec![(None, Zone::Exile)],
        "and created in exile"
    );
    assert!(
        created_tokens_named(&run.events, "Phyrexian Metamorph").is_empty(),
        "the original Metamorph token was not what was created"
    );
    assert!(
        battlefield_tokens_named(run.runner.state(), "Grizzly Bears").is_empty(),
        "no Bears copy entered"
    );
    assert_settled(run.runner.state(), "F1 creature copy");
}

/// F1 decline. Declining the copy leaves a Phyrexian Metamorph creature, which Moonlight
/// exiles: the creature token is created and exiled.
#[test]
fn declined_metamorph_copy_token_is_created_and_exiled_under_moonlight() {
    let run = run_vat(true, MetamorphAnswer::Decline);
    assert!(offered_copy(&run), "the copy is offered: {:?}", run.prompts);
    let created = created_tokens_named(&run.events, "Phyrexian Metamorph");
    assert_eq!(created.len(), 1, "the creature token is created once");
    assert_eq!(
        zone_moves_of(&run.events, created[0]),
        vec![(None, Zone::Exile)],
        "and created in exile"
    );
    assert_settled(run.runner.state(), "F1 decline");
}

// ---------------------------------------------------------------------------
// F4 — a substituted creation delivers the substitute, not the replaced copy body.
// ---------------------------------------------------------------------------

/// DECLARED SYNTHETIC: a tapped copy maker as an instant. The printed shape is a triggered
/// ability, not a spell: Compy Swarm's "create a tapped token that's a copy of this creature"
/// (end step) is the nearest printed donor, and no printed instant or sorcery makes a tapped
/// copy token. The row tests the substitution seam's retention of the creating instruction's
/// tapped state for a copy batch, not that card.
const COPY_CREATURE_TAPPED: &str =
    "Create a tapped token that's a copy of target creature you control.";

/// Bone Offering's printed adventure text (Scryfall), cast here as a zero-cost instant
/// fixture: a printed tapped creature-token maker.
const BONE_OFFERING: &str = "Create a tapped 4/1 black Skeleton creature token with menace.";

/// F4. CR 614.1a + CR 707.9b: Urza copies a noncreature artifact "except it's a 1/1
/// Soldier creature in addition to its other types", which makes the copy a creature
/// token, so Divine Visitation substitutes its 4/4 Angels for it. The Angel is what is
/// created: no Soldier artifact copy is delivered beside it, and the replacement is not
/// consumed for a body that is then delivered anyway.
#[test]
fn divine_visitation_substitutes_urza_copy_of_a_noncreature_artifact() {
    let (mut scenario, urza, trinket) = urza_scenario();
    scenario.add_enchantment_from_oracle(P0, "Divine Visitation", DIVINE_VISITATION);
    let mut runner = scenario.build();

    let outcome = runner.activate(urza, 0).target_object(trinket).resolve();
    assert_settled(outcome.state(), "F4 urza");
    assert!(
        battlefield_tokens_named(outcome.state(), TRINKET).is_empty(),
        "the replaced copy body is not delivered"
    );
    let angels = battlefield_tokens_named(outcome.state(), "Angel");
    assert_eq!(angels.len(), 1, "exactly one Angel is created instead");
    let angel = &outcome.state().objects[&angels[0]];
    assert_eq!((angel.power, angel.toughness), (Some(4), Some(4)));
    assert!(angel.has_keyword(&Keyword::Flying) && angel.has_keyword(&Keyword::Vigilance));
}

/// F4 retained-instruction control, plain batch. The Divine Visitation ruling: anything
/// else the creating effect specifies, such as tapped, still applies to the substitute.
#[test]
fn divine_visitation_substitute_keeps_a_plain_batchs_tapped_state() {
    let mut scenario = base_scenario();
    scenario.add_enchantment_from_oracle(P0, "Divine Visitation", DIVINE_VISITATION);
    let soldier = add_instant(&mut scenario, P0, "Bone Offering", BONE_OFFERING);
    let mut runner = scenario.build();

    let outcome = runner.cast(soldier).resolve();
    assert_settled(outcome.state(), "F4 bone offering");
    let angels = battlefield_tokens_named(outcome.state(), "Angel");
    assert_eq!(angels.len(), 1, "one Angel");
    assert!(outcome.state().objects[&angels[0]].tapped, "tapped");
}

/// F4 retained-instruction control, copy batch: a tapped copy of a creature is replaced
/// by a tapped Angel, and the copy-token resolution still completes at priority.
#[test]
fn divine_visitation_substitute_keeps_a_copy_batchs_tapped_state() {
    let mut scenario = base_scenario();
    scenario.add_enchantment_from_oracle(P0, "Divine Visitation", DIVINE_VISITATION);
    let bears = scenario.add_creature(P0, "Grizzly Bears", 2, 2).id();
    let copy = add_instant(&mut scenario, P0, "Tapped Copy", COPY_CREATURE_TAPPED);
    let mut runner = scenario.build();

    let outcome = runner.cast(copy).target_object(bears).resolve();
    assert_settled(outcome.state(), "F4 tapped copy");
    assert_eq!(
        battlefield_tokens_named(outcome.state(), "Grizzly Bears").len(),
        0,
        "the replaced copy is not delivered"
    );
    let angels = battlefield_tokens_named(outcome.state(), "Angel");
    assert_eq!(angels.len(), 1, "one Angel");
    assert!(outcome.state().objects[&angels[0]].tapped, "tapped");
}

// ---------------------------------------------------------------------------
// F2 — entry applicability reads the entrant as it would exist on the battlefield.
// ---------------------------------------------------------------------------

/// Verbatim Oracle text of Opalescence (Scryfall).
const OPALESCENCE: &str = "Each other non-Aura enchantment is a creature in addition to its \
other types and has base power and base toughness each equal to its mana value.";

/// Verbatim Oracle text of Extravagant Replication (Scryfall).
const EXTRAVAGANT_REPLICATION: &str =
    "At the beginning of your upkeep, create a token that's a copy of another target nonland \
permanent you control.";

/// Pass priority and answer targets until Extravagant Replication's upkeep trigger has been
/// aimed at `target` and sits on the stack with P0 holding priority.
fn aim_replication_trigger(runner: &mut GameRunner, target: ObjectId) {
    for _ in 0..80 {
        match runner.state().waiting_for.clone() {
            WaitingFor::TriggerTargetSelection { .. } => {
                runner
                    .act(GameAction::ChooseTarget {
                        target: Some(TargetRef::Object(target)),
                    })
                    .expect("aim the trigger");
            }
            WaitingFor::Priority { player } if player == P0 && !runner.state().stack.is_empty() => {
                return;
            }
            WaitingFor::Priority { .. } => {
                runner.act(GameAction::PassPriority).expect("pass priority");
            }
            WaitingFor::DeclareAttackers { .. } => {
                runner
                    .act(GameAction::DeclareAttackers {
                        attacks: Vec::new(),
                        bands: Vec::new(),
                    })
                    .expect("declare no attackers");
            }
            other => panic!("unexpected {other:?} before the trigger"),
        }
    }
    panic!(
        "Extravagant Replication's trigger never reached the stack: turn {} {:?} bf {:?}",
        runner.state().turn_number,
        runner.state().phase,
        runner
            .state()
            .battlefield
            .iter()
            .map(|i| runner.state().objects[i].name.clone())
            .collect::<Vec<_>>()
    );
}

/// F2. CR 614.12: under Opalescence the token copy of Opalescence (an Enchantment) is a
/// creature as it would exist on the battlefield, so Hallowed Moonlight — resolved in
/// response to Extravagant Replication's upkeep trigger — creates it in exile. The same
/// copy without Hallowed Moonlight enters.
fn replication_copies_opalescence(moonlight: bool) -> (GameRunner, Vec<GameEvent>) {
    replication_run(moonlight, |scenario| {
        let opalescence = {
            let mut card = scenario.add_enchantment_from_oracle(P0, "Opalescence", OPALESCENCE);
            card.with_mana_cost(ManaCost::generic(4));
            card.id()
        };
        // Opalescence makes Extravagant Replication a creature with power and toughness equal
        // to its mana value ({2}{U}{U}{U}), so it survives only with that cost.
        scenario
            .add_enchantment_from_oracle(P0, "Extravagant Replication", EXTRAVAGANT_REPLICATION)
            .with_mana_cost(ManaCost::generic(5));
        opalescence
    })
}

/// Resolve Extravagant Replication's upkeep trigger on the permanent `setup` builds (and
/// returns), with Hallowed Moonlight resolved in response when `moonlight`.
fn replication_run(
    moonlight: bool,
    setup: impl FnOnce(&mut GameScenario) -> ObjectId,
) -> (GameRunner, Vec<GameEvent>) {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    scenario.with_library_top(P0, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_library_top(P1, &["Island", "Island", "Island", "Island", "Island"]);
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let target = setup(&mut scenario);
    let mut runner = scenario.build();
    aim_replication_trigger(&mut runner, target);
    let mut events = Vec::new();
    if moonlight {
        let outcome = runner.cast(hallowed).resolve();
        events.extend(outcome.events().iter().cloned());
    }
    for _ in 0..20 {
        match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => break,
            WaitingFor::Priority { .. } => {
                let result = runner.act(GameAction::PassPriority).expect("pass priority");
                events.extend(result.events);
            }
            // CR 704.5j: the legendary copy that entered; keep it (the newest candidate).
            WaitingFor::ChooseLegend { candidates, .. } => {
                let keep = *candidates.iter().max().expect("legend candidates");
                let result = runner
                    .act(GameAction::ChooseLegend { keep })
                    .expect("keep the copy");
                events.extend(result.events);
            }
            other => panic!("unexpected {other:?} resolving the trigger"),
        }
    }
    (runner, events)
}

#[test]
fn token_copy_of_opalescence_enters_without_moonlight() {
    let (runner, events) = replication_copies_opalescence(false);
    assert_eq!(
        battlefield_tokens_named(runner.state(), "Opalescence").len(),
        1,
        "the copy enters (the Opalescence token is on the battlefield)"
    );
    assert_eq!(created_tokens_named(&events, "Opalescence").len(), 1);
}

#[test]
fn moonlight_creates_the_token_copy_of_opalescence_in_exile() {
    let (runner, events) = replication_copies_opalescence(true);
    let created = created_tokens_named(&events, "Opalescence");
    assert_eq!(created.len(), 1, "the copy is created once");
    assert_eq!(
        zone_moves_of(&events, created[0]),
        vec![(None, Zone::Exile)],
        "as a creature entering without having been cast, it is created in exile"
    );
    assert!(
        battlefield_tokens_named(runner.state(), "Opalescence").is_empty(),
        "no battlefield entry"
    );
}

/// F2, liminal entry. CR 614.12: with March of the Machines the Vat copy a Metamorph token
/// chooses is, as it would exist on the battlefield, an artifact creature, so Hallowed Moonlight
/// — read through the entrant projection at the token's own entry — creates it in exile; without
/// March of the Machines the same copy enters.
#[test]
fn moonlight_reads_the_liminal_entrant_through_the_battlefield_projection() {
    let animated = run_vat_with(true, true, MetamorphAnswer::CopyVat);
    let created = created_tokens_named(&animated.events, "Mimic Vat");
    assert_eq!(created.len(), 1, "the selected copy is created once");
    assert_eq!(
        zone_moves_of(&animated.events, created[0]),
        vec![(None, Zone::Exile)],
        "an animated Vat copy is a creature entering"
    );
    assert!(
        battlefield_tokens_named(animated.runner.state(), "Mimic Vat").is_empty(),
        "no Vat copy entered"
    );
    let plain = run_vat_with(true, false, MetamorphAnswer::CopyVat);
    assert_eq!(
        battlefield_tokens_named(plain.runner.state(), "Mimic Vat").len(),
        1,
        "without March of the Machines the same copy enters"
    );
}

/// Verbatim Oracle text of Erebos, God of the Dead (Scryfall).
const EREBOS: &str = "Indestructible\nAs long as your devotion to black is less than five, \
Erebos isn't a creature. (Each {B} in the mana costs of permanents you control counts toward \
your devotion to black.)\nYour opponents can't gain life.\n{1}{B}, Pay 2 life: Draw a card.";

/// F1 (copied statics, CR 707.2 + CR 614.12). Extravagant Replication copies Erebos, God of
/// the Dead with Hallowed Moonlight resolved in response. The copy's own static makes it a
/// noncreature below five devotion to black, so it enters; at five devotion (Erebos, plus two
/// Black Knights' {B}{B} each) it is a creature, so it is created in exile. The batch's
/// flattened spec has no statics and reads as a creature in both games.
fn replication_copies_erebos(black_knights: usize) -> (GameRunner, Vec<GameEvent>) {
    replication_run(true, |scenario| {
        let erebos = {
            let mut card =
                scenario.add_creature_from_oracle(P0, "Erebos, God of the Dead", 7, 5, EREBOS);
            card.as_enchantment()
                .as_creature()
                .as_legendary()
                .with_subtypes(vec!["God"])
                .with_mana_cost(ManaCost::Cost {
                    shards: vec![ManaCostShard::Black],
                    generic: 3,
                });
            card.id()
        };
        for _ in 0..black_knights {
            scenario
                .add_creature(P0, "Black Knight", 2, 2)
                .with_mana_cost(ManaCost::Cost {
                    shards: vec![ManaCostShard::Black, ManaCostShard::Black],
                    generic: 0,
                });
        }
        scenario
            .add_enchantment_from_oracle(P0, "Extravagant Replication", EXTRAVAGANT_REPLICATION)
            .with_mana_cost(ManaCost::generic(5));
        erebos
    })
}

#[test]
fn moonlight_lets_a_low_devotion_erebos_copy_enter() {
    let (runner, events) = replication_copies_erebos(0);
    assert_eq!(
        created_tokens_named(&events, "Erebos, God of the Dead").len(),
        1
    );
    assert_eq!(
        battlefield_tokens_named(runner.state(), "Erebos, God of the Dead").len(),
        1,
        "the copy is not a creature (its own static, devotion 1), so Moonlight leaves it"
    );
}

#[test]
fn moonlight_creates_a_high_devotion_erebos_copy_in_exile() {
    let (runner, events) = replication_copies_erebos(2);
    let created = created_tokens_named(&events, "Erebos, God of the Dead");
    assert_eq!(created.len(), 1, "the copy is created once");
    assert_eq!(
        zone_moves_of(&events, created[0]),
        vec![(None, Zone::Exile)],
        "at five devotion the copy is a creature entering"
    );
    assert!(battlefield_tokens_named(runner.state(), "Erebos, God of the Dead").is_empty());
}

// ---------------------------------------------------------------------------
// A prompt raised by the post-copy rediscovery keeps the chosen copy's entry completion.
// ---------------------------------------------------------------------------

const SCULPTING_STEEL: &str =
    "You may have this artifact enter as a copy of any artifact on the battlefield.";
const TRISKELION: &str = "This creature enters with three +1/+1 counters on it.\nRemove a +1/+1 counter from this creature: It deals 1 damage to any target.";
const ROOT_MAZE: &str = "Artifacts and lands enter tapped.";
/// Verbatim Oracle text of Saw in Half (Scryfall).
const SAW_IN_HALF: &str = "Destroy target creature. If that creature dies this way, its controller creates two tokens that are copies of that creature, except their power is half that creature's power and their toughness is half that creature's toughness. Round up each time.";
const ARCHELOS: &str = "As long as Archelos is tapped, other permanents enter tapped.\nAs long as Archelos is untapped, other permanents enter untapped.";

/// CR 616.1c + CR 614.12 + CR 616.1f: Extravagant Replication copies Sculpting Steel; the token's
/// own copy replacement is accepted and Triskelion chosen. Root Maze (artifacts enter tapped)
/// and untapped Archelos (other permanents enter untapped) then compete for the copy's entry, so
/// the rediscovery raises an ordering prompt. Answering it with `order` resumes the chosen copy's
/// entry completion: the token is Triskelion with its three +1/+1 counters, and it enters tapped
/// when Root Maze is applied last... — whichever applies last decides the tapped state.
/// Returns the Triskelion token and its tapped state, and the prompts seen.
fn replication_steel_becomes_triskelion(order: usize, persist: bool) -> (GameRunner, Vec<String>) {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    scenario.with_library_top(P0, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_library_top(P1, &["Island", "Island", "Island", "Island", "Island"]);
    let steel = scenario
        .add_artifact_from_oracle(P0, "Sculpting Steel", SCULPTING_STEEL)
        .id();
    scenario
        .add_creature_from_oracle(P0, "Triskelion", 1, 1, TRISKELION)
        .as_artifact_creature()
        .with_subtypes(vec!["Construct"]);
    scenario.add_enchantment_from_oracle(P0, "Root Maze", ROOT_MAZE);
    scenario
        .add_creature_from_oracle(P0, "Archelos, Lagoon Mystic", 2, 2, ARCHELOS)
        .as_legendary();
    scenario
        .add_enchantment_from_oracle(P0, "Extravagant Replication", EXTRAVAGANT_REPLICATION)
        .with_mana_cost(ManaCost::generic(5));
    let mut runner = scenario.build();
    aim_replication_trigger(&mut runner, steel);
    let mut prompts = Vec::new();
    for _ in 0..40 {
        let result = match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => break,
            WaitingFor::Priority { .. } => runner.act(GameAction::PassPriority),
            WaitingFor::ReplacementChoice {
                candidates, kind, ..
            } => {
                prompts.push(format!("{kind:?}"));
                // Save and reopen on the prompt the post-copy rediscovery raised: the held
                // settlement must survive the round trip.
                if persist && prompts.iter().any(|p| p == "CopyTargetChoice") {
                    let json =
                        serde_json::to_string(&PersistedGameState::capture(runner.state().clone()))
                            .expect("state serializes");
                    let restored = serde_json::from_str::<PersistedGameState>(&json)
                        .expect("persisted state decodes")
                        .prepare_for_restore(PersistedRestoreFinalization::DeferUntilRehydrated)
                        .expect("persisted state is admissible")
                        .finalize_after_rehydration(|_| Ok(()))
                        .expect("restored state is publishable");
                    runner = GameRunner::from_state(restored);
                }
                let accept = candidates
                    .iter()
                    .position(|c| c.description.contains("enter as a copy"));
                let index = accept.unwrap_or(order.min(candidates.len() - 1));
                runner.act(GameAction::ChooseReplacement { index })
            }
            WaitingFor::CopyTargetChoice { valid_targets, .. } => {
                prompts.push("CopyTargetChoice".to_string());
                let triskelion = *valid_targets
                    .iter()
                    .find(|id| runner.state().objects[id].name == "Triskelion")
                    .expect("Triskelion is a legal copy model");
                runner.act(GameAction::ChooseTarget {
                    target: Some(TargetRef::Object(triskelion)),
                })
            }
            WaitingFor::ChooseLegend { candidates, .. } => {
                let keep = *candidates.iter().max().expect("legend candidates");
                runner.act(GameAction::ChooseLegend { keep })
            }
            other => panic!("unexpected prompt {other:?} after {prompts:?}"),
        };
        result.unwrap_or_else(|e| {
            panic!(
                "answer rejected: {e:?}; prompts {prompts:?}; waiting {:?}",
                runner.state().waiting_for
            )
        });
    }
    (runner, prompts)
}

#[test]
fn an_ordering_prompt_after_the_chosen_copy_keeps_the_copys_entry_counters() {
    for persist in [false, true] {
        for order in [0, 1] {
            let (runner, prompts) = replication_steel_becomes_triskelion(order, persist);
            assert!(
                prompts.iter().any(|p| p == "CopyTargetChoice")
                    && prompts.iter().filter(|p| p.starts_with("Order")).count() >= 1,
                "the copy was chosen and the rediscovery then asked an ordering question: {prompts:?}"
            );
            let tokens = battlefield_tokens_named(runner.state(), "Triskelion");
            assert_eq!(
                tokens.len(),
                1,
                "order {order}: the Triskelion copy entered: {prompts:?}"
            );
            let token = &runner.state().objects[&tokens[0]];
            assert_eq!(
                token
                    .counters
                    .get(&engine::types::counter::CounterType::Plus1Plus1)
                    .copied(),
                Some(3),
                "order {order}, persist {persist}: the copy's own enters-with counters survive"
            );
            // The ordering answer decides the tapped state: the replacement applied last wins.
            assert_eq!(
                token.tapped,
                order == 0,
                "order {order}: Root Maze last means tapped"
            );
            assert_settled(runner.state(), "resumed copy entry");
        }
    }
}

const EREBOS_BLEAK_HEARTED: &str = "Indestructible\nAs long as your devotion to black is less than five, Erebos isn't a creature.\nWhenever another creature you control dies, you may pay 2 life. If you do, draw a card.\n{1}{B}, Sacrifice another creature: Target creature gets -2/-1 until end of turn.";
const CLONE_LEGION: &str =
    "For each creature target player controls, create a token that's a copy of that creature.";

/// CR 614.12 + CR 614.4 (Clone Legion ruling: the tokens all enter at the same time). P1 controls
/// both Erebos gods (creatures at six devotion to black); P0 has four. Clone Legion makes a copy
/// of each; Hallowed Moonlight resolves in response. Each God copy is a noncreature against P0's
/// pre-entry devotion of four, so neither is exiled: the first copy's black symbol does not count
/// toward the second's entry.
#[test]
fn clone_legion_god_copies_do_not_count_each_others_devotion_under_moonlight() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    scenario.with_library_top(P0, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_library_top(P1, &["Island", "Island", "Island", "Island", "Island"]);
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let legion = add_sorcery(&mut scenario, P0, "Clone Legion", CLONE_LEGION);
    let black = |n: usize| ManaCost::Cost {
        shards: vec![ManaCostShard::Black; n],
        generic: 0,
    };
    for _ in 0..2 {
        scenario
            .add_creature(P0, "Black Knight", 2, 2)
            .with_mana_cost(black(2));
    }
    for _ in 0..2 {
        scenario
            .add_creature(P1, "Black Knight", 2, 2)
            .with_mana_cost(black(2));
    }
    for (name, oracle) in [
        ("Erebos, God of the Dead", EREBOS),
        ("Erebos, Bleak-Hearted", EREBOS_BLEAK_HEARTED),
    ] {
        let mut card = scenario.add_creature_from_oracle(P1, name, 7, 5, oracle);
        card.as_enchantment()
            .as_creature()
            .as_legendary()
            .with_subtypes(vec!["God"])
            .with_mana_cost(ManaCost::Cost {
                shards: vec![ManaCostShard::Black],
                generic: 3,
            });
    }
    let mut runner = scenario.build();
    runner.cast(legion).target_player(P1).commit();
    let mut events = Vec::new();
    let outcome = runner.cast(hallowed).resolve();
    events.extend(outcome.events().iter().cloned());
    for _ in 0..30 {
        match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => break,
            WaitingFor::Priority { .. } => {
                let result = runner.act(GameAction::PassPriority).expect("pass priority");
                events.extend(result.events);
            }
            WaitingFor::ChooseLegend { candidates, .. } => {
                let keep = *candidates.iter().max().expect("legend candidates");
                let result = runner.act(GameAction::ChooseLegend { keep }).expect("keep");
                events.extend(result.events);
            }
            other => panic!("unexpected {other:?}"),
        }
    }
    for name in ["Erebos, God of the Dead", "Erebos, Bleak-Hearted"] {
        let created = created_tokens_named(&events, name);
        assert_eq!(created.len(), 1, "{name} copy created once");
        assert_eq!(
            zone_moves_of(&events, created[0]),
            vec![(None, Zone::Battlefield)],
            "{name} copy enters the battlefield (a noncreature at pre-entry devotion four)"
        );
    }
}

/// CR 616.1c + CR 614.12: with Grumgully's batch entry counter on the Metamorph token's creation,
/// the own copy is still offered before Hallowed Moonlight's redirect. Choosing Mimic Vat (a
/// noncreature artifact, which Grumgully's creature counter does not reach) enters without a
/// counter; declining still creates and exiles the creature token.
#[test]
fn grumgullys_batch_counter_does_not_bypass_the_metamorph_copy_choice() {
    let vat = run_vat_full(true, false, true, MetamorphAnswer::CopyVat);
    assert!(offered_copy(&vat), "the copy is offered: {:?}", vat.prompts);
    let tokens = battlefield_tokens_named(vat.runner.state(), "Mimic Vat");
    assert_eq!(tokens.len(), 1, "the noncreature Vat copy entered");
    assert!(
        vat.runner.state().objects[&tokens[0]].counters.is_empty(),
        "Grumgully's counter does not reach a noncreature copy"
    );
    let declined = run_vat_full(true, false, true, MetamorphAnswer::Decline);
    assert!(
        offered_copy(&declined),
        "the copy is offered: {:?}",
        declined.prompts
    );
    let created = created_tokens_named(&declined.events, "Phyrexian Metamorph");
    assert_eq!(created.len(), 1, "the creature token is created once");
    assert_eq!(
        zone_moves_of(&declined.events, created[0]),
        vec![(None, Zone::Exile)],
        "and created in exile"
    );
}

/// CR 616.1f + CR 707.2 + CR 707.2b: the selected copiable values survive the
/// rediscovery prompt. P1 casts Sculpting Steel as Triskelion; P0's Replication
/// copies a separate, plain Steel and chooses P1's copied Steel by ID. CR 800.4a:
/// P1 then concedes, removing that model and its layer-one copy effect. Re-reading
/// its printed Steel values must not replace the Triskelion values already chosen.
#[test]
fn a_model_that_leaves_during_the_rediscovery_prompt_does_not_change_the_selected_copy() {
    let mut scenario = GameScenario::new_n_player(3, 42);
    scenario.at_phase(Phase::PreCombatMain);
    for player in [P0, P1, PlayerId(2)] {
        scenario.with_library_top(player, &["Island", "Island", "Island", "Island", "Island"]);
    }
    let steel = scenario
        .add_artifact_from_oracle(P0, "Sculpting Steel", SCULPTING_STEEL)
        .with_mana_cost(ManaCost::generic(3))
        .id();
    let triskelion = scenario
        .add_creature_from_oracle(P0, "Triskelion", 1, 1, TRISKELION)
        .as_artifact_creature()
        .with_subtypes(vec!["Construct"])
        .with_mana_cost(ManaCost::generic(6))
        .id();
    let model = scenario
        .add_artifact_to_hand_from_oracle(P1, "Sculpting Steel", SCULPTING_STEEL)
        .with_mana_cost(ManaCost::generic(3))
        .id();
    for _ in 0..3 {
        scenario.add_basic_land(P1, engine::types::mana::ManaColor::Blue);
    }
    let root_maze = scenario
        .add_enchantment_from_oracle(P0, "Root Maze", ROOT_MAZE)
        .id();
    let archelos = scenario
        .add_creature_from_oracle(P0, "Archelos, Lagoon Mystic", 2, 4, ARCHELOS)
        .as_legendary()
        .with_subtypes(vec!["Turtle", "Shaman"])
        .id();
    scenario.add_enchantment_from_oracle(P0, "Extravagant Replication", EXTRAVAGANT_REPLICATION);
    let mut runner = scenario.build();

    // Establish the model's copy through a real cast on its controller's turn.
    for _ in 0..80 {
        if runner.state().active_player == P1
            && runner.state().phase == Phase::PreCombatMain
            && matches!(runner.state().waiting_for, WaitingFor::Priority { player } if player == P1)
        {
            break;
        }
        match runner.state().waiting_for {
            WaitingFor::Priority { .. } => runner.act(GameAction::PassPriority),
            WaitingFor::DeclareAttackers { .. } => runner.act(GameAction::DeclareAttackers {
                attacks: Vec::new(),
                bands: Vec::new(),
            }),
            ref other => panic!("unexpected prompt before P1's cast: {other:?}"),
        }
        .expect("advance to P1's main phase");
    }
    assert_eq!(runner.state().active_player, P1);
    assert_eq!(runner.state().phase, Phase::PreCombatMain);
    assert!(matches!(
        runner.state().waiting_for,
        WaitingFor::Priority { player } if player == P1
    ));
    runner.cast(model).replacement_choice(0).resolve();
    match &runner.state().waiting_for {
        WaitingFor::CopyTargetChoice {
            player,
            source_id,
            valid_targets,
            ..
        } => {
            assert_eq!(*player, P1);
            assert_eq!(
                *source_id, model,
                "the cast Steel makes its own copy choice"
            );
            assert!(valid_targets.contains(&triskelion));
        }
        other => panic!("expected P1's cast Steel copy choice, got {other:?}"),
    }
    runner
        .act(GameAction::ChooseTarget {
            target: Some(TargetRef::Object(triskelion)),
        })
        .expect("P1's Steel copies the printed Triskelion");
    for _ in 0..20 {
        match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => break,
            WaitingFor::Priority { .. } => runner.act(GameAction::PassPriority),
            WaitingFor::ReplacementChoice { player, kind, .. } => {
                assert_eq!(player, P1);
                assert_eq!(kind, ReplacementChoiceKind::Order);
                runner.act(GameAction::ChooseReplacement { index: 0 })
            }
            other => panic!("unexpected prompt finishing P1's Steel: {other:?}"),
        }
        .expect("finish P1's cast Steel");
    }
    assert_settled(runner.state(), "P1's cast Steel");
    let copied_model = &runner.state().objects[&model];
    assert_eq!(copied_model.owner, P1);
    assert_eq!(copied_model.zone, Zone::Battlefield);
    assert_eq!(copied_model.base_name, "Sculpting Steel");
    assert_eq!(copied_model.name, "Triskelion");
    assert!(copied_model
        .card_types
        .core_types
        .contains(&CoreType::Creature));
    assert_eq!(
        copied_model
            .counters
            .get(&engine::types::counter::CounterType::Plus1Plus1),
        Some(&3),
        "the model's cast copy acquired Triskelion's entry counters"
    );
    let model_copy = copied_model
        .layer1_copy_effect
        .expect("the cast model has an installed layer-one copy effect");
    assert!(runner
        .state()
        .transient_continuous_effects
        .iter()
        .any(|effect| {
            effect.id == model_copy.continuous_effect_id
            && effect.source_id == model
            && effect.modifications.iter().any(|modification| matches!(
                modification,
                ContinuousModification::CopyValues { values, .. } if values.name == "Triskelion"
            ))
        }));
    assert_eq!(runner.state().objects[&steel].name, "Sculpting Steel");
    assert!(runner.state().objects[&steel].layer1_copy_effect.is_none());

    aim_replication_trigger(&mut runner, steel);
    for _ in 0..10 {
        if !matches!(runner.state().waiting_for, WaitingFor::Priority { .. }) {
            break;
        }
        assert!(
            !runner.state().stack.is_empty(),
            "Replication must not finish before the copy choice"
        );
        runner
            .act(GameAction::PassPriority)
            .expect("resolve Replication");
    }
    let token_id = match &runner.state().waiting_for {
        WaitingFor::ReplacementChoice {
            player,
            kind,
            candidates,
            ..
        } => {
            assert_eq!(*player, P0);
            assert_eq!(*kind, ReplacementChoiceKind::OptionalBranch);
            assert_eq!(candidates.len(), 2);
            let token_id = candidates[0].source_id;
            assert!(candidates
                .iter()
                .all(|candidate| candidate.source_id == token_id));
            assert!(candidates[0].description.contains("enter as a copy"));
            token_id
        }
        other => panic!("expected token Steel's own optional copy replacement, got {other:?}"),
    };
    runner
        .act(GameAction::ChooseReplacement { index: 0 })
        .expect("accept the token Steel's own copy replacement");
    match &runner.state().waiting_for {
        WaitingFor::CopyTargetChoice {
            player,
            source_id,
            valid_targets,
            ..
        } => {
            assert_eq!(*player, P0);
            assert_eq!(*source_id, token_id);
            assert!(
                valid_targets.contains(&model),
                "P1's copied Steel is a legal model"
            );
            assert!(
                valid_targets.contains(&triskelion),
                "the same-named printed Triskelion is a distinct option"
            );
            assert_ne!(model, triskelion);
        }
        other => panic!("expected the token's copy-model choice, got {other:?}"),
    }
    runner
        .act(GameAction::ChooseTarget {
            target: Some(TargetRef::Object(model)),
        })
        .expect("choose P1's copied Steel by ID, not the printed Triskelion");
    let ordering = match &runner.state().waiting_for {
        WaitingFor::ReplacementChoice {
            player,
            kind,
            candidates,
            ..
        } => {
            assert_eq!(*player, P0);
            assert_eq!(*kind, ReplacementChoiceKind::Order);
            assert_eq!(
                candidates.len(),
                2,
                "only Root Maze and untapped Archelos order entry"
            );
            assert!(candidates
                .iter()
                .any(|candidate| candidate.source_id == root_maze));
            assert!(candidates
                .iter()
                .any(|candidate| candidate.source_id == archelos));
            candidates.clone()
        }
        other => panic!("expected mandatory post-copy entry ordering, got {other:?}"),
    };
    assert!(!runner.state().objects[&archelos].tapped);
    let settlement = runner.state().liminal_entries[&token_id]
        .copy_settlement
        .as_ref()
        .expect("the post-copy ordering prompt holds the chosen copy");
    assert_eq!(settlement.target_id, model);
    assert_eq!(settlement.copy_values.name, "Triskelion");
    assert!(
        !runner.state().battlefield.contains(&token_id),
        "entry is still suspended"
    );

    runner
        .act(GameAction::Concede { player_id: P1 })
        .expect("the chosen model's owner concedes during rediscovery ordering");
    // Negative-control witness: a live re-read now sees a plain, noncreature Steel,
    // not Triskelion. An ordinary printed Triskelion model would not discriminate.
    let departed_model = &runner.state().objects[&model];
    assert!(!runner.state().battlefield.contains(&model));
    assert_eq!(departed_model.zone, Zone::Exile);
    assert_eq!(departed_model.name, "Sculpting Steel");
    assert!(!departed_model
        .card_types
        .core_types
        .contains(&CoreType::Creature));
    assert!(departed_model.layer1_copy_effect.is_none());
    assert!(
        !runner
            .state()
            .transient_continuous_effects
            .iter()
            .any(|effect| { effect.id == model_copy.continuous_effect_id }),
        "the model's former Triskelion copy effect was removed"
    );
    match &runner.state().waiting_for {
        WaitingFor::ReplacementChoice {
            player,
            kind,
            candidates,
            ..
        } => {
            assert_eq!(*player, P0);
            assert_eq!(*kind, ReplacementChoiceKind::Order);
            assert_eq!(
                *candidates, ordering,
                "concession preserves the held ordering prompt"
            );
        }
        other => panic!("concession abandoned the held ordering: {other:?}"),
    }
    let root_maze_first = ordering
        .iter()
        .position(|candidate| candidate.source_id == root_maze)
        .expect("Root Maze is an ordering option");
    runner
        .act(GameAction::ChooseReplacement {
            index: root_maze_first,
        })
        .expect("finish entry with Archelos applied last");
    assert_settled(runner.state(), "copy entry after its chosen model leaves");
    assert_eq!(
        battlefield_tokens_named(runner.state(), "Triskelion"),
        vec![token_id]
    );
    let token = &runner.state().objects[&token_id];
    assert_eq!(
        token.name, "Triskelion",
        "captured values, not the departed model's printed Steel"
    );
    assert!(token.is_token);
    assert_eq!(token.controller, P0);
    assert!(token.card_types.core_types.contains(&CoreType::Artifact));
    assert!(token.card_types.core_types.contains(&CoreType::Creature));
    assert!(token
        .card_types
        .subtypes
        .iter()
        .any(|subtype| subtype == "Construct"));
    assert_eq!(
        token
            .counters
            .get(&engine::types::counter::CounterType::Plus1Plus1),
        Some(&3),
        "the selected Triskelion's own enters-with counters survive"
    );
    assert!(
        !token.tapped,
        "Root Maze first and untapped Archelos last means untapped"
    );
}

/// Verbatim Oracle text of Superior Spider-Man (Scryfall).
const SUPERIOR_SPIDER_MAN: &str =
    "Mind Swap — You may have Superior Spider-Man enter as a copy of \
any creature card in a graveyard, except his name is Superior Spider-Man and he's a 4/4 Spider \
Human Hero in addition to his other types. When you do, exile that card.";

/// CR 603.12 + CR 608.2c: Feldon of the Third Path copies Superior Spider-Man from the graveyard
/// (the token is an artifact); the token's own copy replacement is accepted and Hill Giant chosen.
/// Root Maze (artifacts enter tapped) and untapped Archelos then compete, so the rediscovery
/// raises an ordering prompt, and the chosen copy completes only after it is answered. Mind
/// Swap's "when you do, exile that card" rider must still reach the Hill Giant the player chose.
#[test]
fn a_resumed_copy_keeps_its_riders_selected_card_referent() {
    let mut scenario = GameScenario::new();
    scenario.at_phase(Phase::PreCombatMain);
    scenario.with_library_top(P0, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_library_top(P1, &["Island", "Island", "Island", "Island", "Island"]);
    scenario.with_mana_pool(
        P0,
        (0..3)
            .map(|_| ManaUnit::new(ManaType::Red, ObjectId(0), false, vec![]))
            .collect(),
    );
    let feldon = scenario
        .add_creature_from_oracle(P0, "Feldon of the Third Path", 2, 3, FELDON)
        .as_legendary()
        .id();
    scenario.add_enchantment_from_oracle(P0, "Root Maze", ROOT_MAZE);
    scenario
        .add_creature_from_oracle(P0, "Archelos, Lagoon Mystic", 2, 4, ARCHELOS)
        .as_legendary()
        .with_subtypes(vec!["Turtle", "Shaman"]);
    let spider = {
        let mut card = scenario.add_creature_to_graveyard(P0, "Superior Spider-Man", 4, 4);
        card.from_oracle_text(SUPERIOR_SPIDER_MAN)
            .as_legendary()
            .with_subtypes(vec!["Spider", "Human", "Hero"]);
        card.id()
    };
    let giant = scenario
        .add_creature_to_graveyard(P0, "Hill Giant", 3, 3)
        .id();
    let mut runner = scenario.build();
    let mut events = runner
        .activate(feldon, 0)
        .target_object(spider)
        .resolve()
        .events()
        .to_vec();
    let mut prompts = Vec::new();
    for _ in 0..40 {
        let result = match runner.state().waiting_for.clone() {
            WaitingFor::Priority { .. } if runner.state().stack.is_empty() => break,
            WaitingFor::Priority { .. } => runner.act(GameAction::PassPriority),
            WaitingFor::ReplacementChoice { candidates, .. } => {
                prompts.push("ReplacementChoice".to_string());
                let accept = candidates
                    .iter()
                    .position(|c| c.description.contains("enter as a copy"));
                if accept.is_none() {
                    assert_eq!(
                        prompts.iter().filter(|p| *p == "CopyTargetChoice").count(),
                        1
                    );
                    assert!(candidates.len() >= 2, "entry replacements compete");
                    prompts.push("Ordering".to_string());
                }
                runner.act(GameAction::ChooseReplacement {
                    index: accept.unwrap_or(0),
                })
            }
            WaitingFor::CopyTargetChoice { valid_targets, .. } => {
                prompts.push("CopyTargetChoice".to_string());
                assert!(
                    valid_targets.contains(&giant),
                    "Hill Giant is a legal model"
                );
                runner.act(GameAction::ChooseTarget {
                    target: Some(TargetRef::Object(giant)),
                })
            }
            WaitingFor::OptionalEffectChoice { .. } => {
                prompts.push("OptionalEffectChoice".to_string());
                runner.act(GameAction::DecideOptionalEffect { accept: true })
            }
            WaitingFor::ChooseLegend { candidates, .. } => {
                let keep = *candidates.iter().max().expect("legend candidates");
                runner.act(GameAction::ChooseLegend { keep })
            }
            other => panic!("unexpected prompt {other:?} after {prompts:?}"),
        };
        events.extend(result.expect("the prompt answer is accepted").events);
    }
    assert!(
        prompts.iter().any(|p| p == "CopyTargetChoice") && prompts.iter().any(|p| p == "Ordering"),
        "the copy was chosen and the rediscovery then asked an ordering question: {prompts:?}"
    );
    assert_eq!(
        runner.state().objects[&giant].zone,
        Zone::Exile,
        "the rider exiled the card the copy was made from: {prompts:?}"
    );
    assert_eq!(
        zone_moves_of(&events, giant),
        vec![(Some(Zone::Graveyard), Zone::Exile)],
        "the selected card is exiled exactly once"
    );
    let tokens = battlefield_tokens_named(runner.state(), "Superior Spider-Man");
    assert_eq!(tokens.len(), 1, "the chosen copy completed entry");
    assert_settled(runner.state(), "resumed copy with rider");
}

/// CR 707.9b + CR 614.6: Saw in Half's halved power and toughness are part of each copy's
/// copiable values, so under Hallowed Moonlight the two Thalia copies are created in exile as 2/1s
/// (half of 3/2, rounded up) — in the journaled birth and its replay — with no battlefield entry.
#[test]
fn moonlight_redirected_saw_in_half_copies_are_born_halved() {
    let mut scenario = base_scenario();
    let hallowed = add_instant(&mut scenario, P0, "Hallowed Moonlight", HALLOWED_MOONLIGHT);
    let saw = add_instant(&mut scenario, P0, "Saw in Half", SAW_IN_HALF);
    let thalia = scenario
        .add_creature_from_oracle(
            P0,
            "Thalia, Heretic Cathar",
            3,
            2,
            "First strike\nCreatures and nonbasic lands your opponents control enter tapped.",
        )
        .as_legendary()
        .with_subtypes(vec!["Human", "Soldier"])
        .id();
    let mut runner = scenario.build();
    cast_hallowed(&mut runner, hallowed);
    let committed = runner.cast(saw).target_object(thalia).commit();
    let pre_state = committed.state().clone();
    let window = pre_state.resolved_rules_journal.entries().len();
    let outcome = committed.resolve();
    let state = outcome.state().clone();
    assert_settled(&state, "redirected Saw in Half copies");
    let created = created_tokens_named(outcome.events(), "Thalia, Heretic Cathar");
    assert_eq!(created.len(), 2, "two copies are created");
    let births: Vec<_> = state
        .resolved_rules_journal
        .entries()
        .iter()
        .skip(window)
        .filter_map(|entry| match entry.command.as_ref() {
            Some(ResolvedRulesCommand::TokenCreation(birth))
                if created.contains(&birth.object.object_id) =>
            {
                Some(birth.clone())
            }
            _ => None,
        })
        .collect();
    assert_eq!(births.len(), 2, "both births are journaled");
    for birth in &births {
        assert_eq!(birth.entry_zone, Some(Zone::Exile), "born in exile");
        assert_eq!(
            zone_moves_of(outcome.events(), birth.object.object_id),
            vec![(None, Zone::Exile)],
            "created in exile and never entered"
        );
        let recorded = state
            .created_tokens_this_turn
            .iter()
            .find(|record| record.object_id == birth.object.object_id)
            .expect("the live birth has a creation snapshot");
        assert_eq!(
            (recorded.power, recorded.toughness),
            (Some(2), Some(1)),
            "the live creation snapshot is the halved 2/1"
        );
        let mut replay = pre_state.clone();
        engine::game::effects::token::apply_resolved_token_creation(&mut replay, birth)
            .expect("the redirected birth replays");
        let replayed = &replay.objects[&birth.object.object_id];
        assert_eq!(
            (replayed.power, replayed.toughness),
            (Some(2), Some(1)),
            "the replayed birth is the halved 2/1"
        );
        assert!(replayed.counters.is_empty(), "no entry counters are placed");
    }
}

